VID.narration = {"look":{"bar":false},"scenes":[{"dur":7.616,"caps":[[0.5,6.59,"Lecture eleven. Flocking. This is how a few simple rules make a flock, with no leader."]],"warp":[[0,0],[0.5,0.9],[7.616,4]]},{"dur":16.695,"caps":[[0.5,4.83,"A flock moves as one, with no leader."],[5.08,11.01,"A predator strikes: nearby birds swerve away."],[11.26,15.59,"Then the flock pulls back together."]],"warp":[[0,0],[0.5,0.5],[5.08,3.6],[11.26,6.4],[16.695,10]]},{"dur":18.321,"caps":[[0.5,6.51,"Too close: the two birds push apart."],[6.76,11.57,"Too far: they pull together."],[11.82,17.03,"In between, the two urges cancel out."]],"warp":[[0,0],[0.5,0.5],[6.76,3.6],[11.82,6.5],[18.321,10]]},{"dur":23.429,"caps":[[0.5,6.67,"A boid only senses flockmates nearby."],[6.92,11.01,"Inside its radius: 4 flockmates."],[11.26,17.83,"It knows each one's distance and direction."],[18.08,22.81,"It sees all round, even behind it."]],"warp":[[0,0],[0.5,0.5],[6.92,3.9],[11.26,5.8],[18.08,8],[23.429,10]]},{"dur":23.243,"caps":[[0.5,6.35,"Rule 1, separation: don't crowd."],[6.6,15.33,"The closer a flockmate, the harder the push."],[15.58,18.47,"So the boid steers away."],[18.72,21.05,"Now nobody is too close."]],"warp":[[0,0],[0.5,0.5],[6.6,2.8],[15.58,5.3],[18.72,7.7],[23.243,10]]},{"dur":19.992,"caps":[[0.5,5.47,"Rule 2, alignment: match your neighbours."],[5.72,9.09,"On average, its neighbours head east."],[9.34,13.27,"It turns a little towards them each step."],[13.52,18.89,"Soon they all head the same way."]],"warp":[[0,0],[0.5,0.5],[5.72,2.9],[9.34,5.1],[13.52,7.7],[19.992,10]]},{"dur":18.321,"caps":[[0.5,4.83,"Rule 3, cohesion: stay with the group."],[5.08,9.97,"It finds the centre of its neighbours."],[10.22,13.27,"And steers towards that centre."],[13.52,16.73,"The group closes up."]],"warp":[[0,0],[0.5,0.5],[5.08,2.9],[10.22,5.1],[13.52,7.7],[18.321,10]]},{"dur":23.336,"caps":[[0.5,6.59,"Each boid adds up its three pushes."],[6.84,10.37,"The sum turns it."],[10.62,15.83,"All boids do this at the same time."],[16.08,21.61,"Out of the chaos, one flock forms."]],"warp":[[0,0],[0.5,0.5],[6.84,3.1],[10.62,5.2],[16.08,9.1],[23.336,14]]},{"dur":20.016,"caps":[[0.5,7.39,"Start them packed: they burst apart."],[7.64,11.49,"Then they gather again."],[11.74,15.19,"Two flocks meet head-on."],[15.44,18.41,"They join and fly on as one flock."]],"warp":[[0,0],[0.5,0.6],[7.64,3.5],[11.74,6.1],[15.44,8.9],[20.016,12]]},{"dur":26.772,"caps":[[0.5,5.71,"An agent senses its world with sensors."],[5.96,12.85,"What it senses right now is its percept."],[13.1,21.11,"Then it acts with actuators: here, a turn."],[21.36,25.93,"The others move too, so it senses again."]],"warp":[[0,0],[0.5,0.5],[5.96,3.1],[13.1,5.3],[21.36,7.7],[26.772,11]]},{"dur":30,"caps":[[0.5,6.35,"Many agents can work together."],[6.6,10.77,"If all 10 talk to each other: 45 links."],[11.02,15.91,"Talking only to neighbours: 10 links."],[16.16,20.73,"One central monitor watches for faults."],[20.98,27.79,"If it breaks, one bad agent infects them all."]],"warp":[[0,0],[0.5,0.5],[6.6,2.9],[11.02,5.7],[16.16,7.7],[20.98,10.3],[30,14]]},{"dur":15.302,"caps":[],"warp":[[0,0],[0.5,0.9],[4.68,2],[9.5,3.1],[15.302,9]]}]};
